"""Loading and reference checks for the batch and reservation ledger."""
import json
from pathlib import Path


def load(root):
    root = Path(root)
    batch = json.loads((root / 'batch.json').read_text())
    ledger = json.loads((root / 'ledger.json').read_text())
    return batch, ledger


def collapse(rows, kind):
    """Identical replays collapse; a changed payload under one ID is an error."""
    result = {}
    for row in rows:
        if row['id'] in result and result[row['id']] != row:
            raise ValueError('conflicting %s replay %s' % (kind, row['id']))
        result[row['id']] = row
    return result


def credentials(batch):
    table = {c['id']: c for c in batch['credentials']}
    if len(table) != len(batch['credentials']):
        raise ValueError('duplicate credential ID')
    if len({r['id'] for r in batch['routes']}) != len(batch['routes']):
        raise ValueError('duplicate route ID')
    for c in table.values():
        if c['pool'] not in batch['budgets']:
            raise ValueError('credential %s uses unknown pool' % c['id'])
        if c['parent'] is not None and c['parent'] not in table:
            raise ValueError('credential %s has unknown parent' % c['id'])
    for route in batch['routes']:
        if any(name not in table for name in route['credentials']):
            raise ValueError('route %s names unknown credential' % route['id'])
    return table

"""Reservation ledger replay at the batch cutoff."""
from .records import collapse, credentials


def replay(batch, ledger):
    """Return {reservation: {key, attempt, units, pools, expires, state}} at batch['as_of']."""
    cutoff = batch['as_of']
    table = credentials(batch)
    attempts = collapse(ledger['attempts'], 'attempt')
    receipts = collapse(ledger['receipts'], 'receipt')
    for attempt in attempts.values():
        if any(name not in table for name in attempt['credentials']):
            raise ValueError('attempt %s names unknown credential' % attempt['id'])
    declared = {r['reservation'] for r in receipts.values() if r['kind'] == 'reserve'}
    for receipt in receipts.values():
        if receipt['kind'] in ('reserve', 'reject') and receipt['attempt'] not in attempts:
            raise ValueError('receipt %s names unknown attempt' % receipt['id'])
        if receipt['kind'] in ('commit', 'release') and receipt['reservation'] not in declared:
            raise ValueError('receipt %s names unknown reservation' % receipt['id'])
    reservations, keys = {}, {}
    for receipt in sorted(receipts.values(), key=lambda r: (r['at'], r['id'])):
        if receipt['at'] > cutoff:
            continue
        kind = receipt['kind']
        if kind in ('reserve', 'reject'):
            attempt = attempts[receipt['attempt']]
            if attempt['at'] > receipt['at']:
                raise ValueError('receipt %s precedes its attempt' % receipt['id'])
        if kind == 'reject':
            continue
        name = receipt['reservation']
        if kind == 'reserve':
            binding = {'key': attempt['key'], 'attempt': attempt['id'], 'units': attempt['units'],
                       'pools': sorted({table[c]['pool'] for c in attempt['credentials']}), 'expires': receipt['expires']}
            if name in reservations:
                if reservations[name]['binding'] != binding:
                    raise ValueError('reservation %s rebound' % name)
            else:
                if attempt['key'] in keys or receipt['expires'] <= receipt['at']:
                    raise ValueError('key reused or reservation %s acknowledged after expiry' % name)
                keys[attempt['key']] = name
                reservations[name] = {'binding': binding, 'state': 'held'}
            continue
        if name not in reservations:
            raise ValueError('terminal receipt %s before reserve' % receipt['id'])
        entry = reservations[name]
        target = 'committed' if kind == 'commit' else 'released'
        if entry['state'] not in ('held', target):
            raise ValueError('contradictory terminal receipts for %s' % name)
        if kind == 'commit' and entry['state'] == 'held' and receipt['at'] >= entry['binding']['expires']:
            raise ValueError('reservation %s committed at or after expiry' % name)
        entry['state'] = target
    result = {}
    for name, entry in sorted(reservations.items()):
        state = entry['state']
        if state == 'held' and entry['binding']['expires'] <= cutoff:
            state = 'expired'
        result[name] = {**entry['binding'], 'state': state}
    return result


def availability(batch, reservations):
    """Remaining allowance per pool at each supplied start: {pool: {str(slot): units}}."""
    def charged(pool, slot):
        return sum(r['units'] for r in reservations.values() if pool in r['pools'] and
                   (r['state'] == 'committed' or r['state'] == 'held' and slot < r['expires']))
    return {pool: {str(t): batch['budgets'][pool] - charged(pool, t) for t in sorted(batch['slots'])}
            for pool in sorted(batch['budgets'])}

"""Route usability and local start options for each request."""
from .records import credentials


def route_options(batch):
    """{request_id: [{route, start, pools}]} sorted by route ID then start; ignores shared allowance."""
    table = credentials(batch)
    options = {}
    for request in sorted(batch['requests'], key=lambda q: q['id']):
        found = []
        for route in sorted(batch['routes'], key=lambda r: r['id']):
            if route['request'] != request['id']:
                continue
            chain = [table[name] for name in route['credentials']]
            if not chain or chain[0]['parent'] is not None or chain[-1]['id'] not in request['leaves']:
                continue
            if any(child['parent'] != parent['id'] for parent, child in zip(chain, chain[1:])):
                continue
            if any(not set(request['scopes']) <= set(c['scopes']) for c in chain):
                continue
            pools = sorted({c['pool'] for c in chain})
            for t in sorted(batch['slots']):
                finish = t + request['duration']
                if t < request['earliest'] or finish > request['latest']:
                    continue
                if any(t < c['start'] or finish > c['end'] for c in chain):
                    continue
                found.append({'route': route['id'], 'start': t, 'pools': pools})
        options[request['id']] = found
    return options

"""Assign each call a route and start within worker and allowance limits."""


class ScheduleError(Exception):
    """The batch cannot be scheduled under the supplied rules."""


def schedule(batch, options, available):
    """Prototype: take the first option that still fits for each request, in request-ID order."""
    remaining = {pool: dict(row) for pool, row in available.items()}
    workers = {str(t): batch['workers'][str(t)] for t in batch['slots']}
    units = {q['id']: q['units'] for q in batch['requests']}
    chosen = {}
    for request_id in sorted(options):
        need = units[request_id]
        for option in options[request_id]:
            later = [str(t) for t in batch['slots'] if t >= option['start']]
            if workers[str(option['start'])] < need:
                continue
            if any(remaining[p][t] < need for p in option['pools'] for t in later):
                continue
            workers[str(option['start'])] -= need
            for pool in option['pools']:
                for t in later:
                    remaining[pool][t] -= need
            chosen[request_id] = option
            break
        else:
            raise ScheduleError('no remaining route/start for %s' % request_id)
    return chosen

import json

from reconcile.reservations import availability, replay
from reconcile.runner import main


def batch(requests, budgets=None, workers=None):
    return {'batch': 'T', 'customer': 'Example', 'as_of': 1, 'slots': [1, 2],
            'workers': workers or {'1': 4, '2': 4}, 'budgets': budgets or {'root': 10, 'leaf': 4},
            'credentials': [{'id': 'root', 'parent': None, 'scopes': ['run'], 'start': 0, 'end': 5, 'pool': 'root'},
                            {'id': 'leaf', 'parent': 'root', 'scopes': ['run'], 'start': 0, 'end': 5, 'pool': 'leaf'}],
            'requests': [{'id': q, 'scopes': ['run'], 'units': u, 'duration': 1, 'earliest': 1, 'latest': 3, 'leaves': ['leaf']}
                         for q, u in requests],
            'routes': [{'id': 'via-' + q, 'request': q, 'credentials': ['root', 'leaf']} for q, _ in requests]}


def write(root, batch_doc, attempts=(), receipts=()):
    root.mkdir(parents=True, exist_ok=True)
    (root / 'batch.json').write_text(json.dumps(batch_doc))
    (root / 'ledger.json').write_text(json.dumps({'attempts': list(attempts), 'receipts': list(receipts)}))
    return root


HOLD = [{'id': 'a1', 'key': 'k1', 'at': 0, 'credentials': ['root', 'leaf'], 'units': 2, 'transport': 'response'}]


def test_single_call_schedule(tmp_path):
    data = write(tmp_path / 'data', batch([('q1', 2)]))
    target = tmp_path / 'out' / 'schedule.json'
    assert main(['--data', str(data), '--output', str(target)]) == 0
    assert json.loads(target.read_text())['calls'] == [{'request': 'q1', 'route': 'via-q1', 'start': 1, 'pools': ['leaf', 'root']}]


def test_held_reservation_until_expiry():
    receipts = [{'id': 'r1', 'kind': 'reserve', 'at': 0, 'reservation': 'h1', 'attempt': 'a1', 'expires': 2}]
    doc = batch([])
    state = replay(doc, {'attempts': HOLD, 'receipts': receipts})
    assert state['h1']['state'] == 'held'
    assert availability(doc, state)['leaf'] == {'1': 2, '2': 4}


def test_conflicting_replay_keeps_existing_schedule(tmp_path):
    receipts = [{'id': 'r1', 'kind': 'reserve', 'at': 0, 'reservation': 'h1', 'attempt': 'a1', 'expires': 2},
                {'id': 'r1', 'kind': 'reserve', 'at': 0, 'reservation': 'h1', 'attempt': 'a1', 'expires': 3}]
    data = write(tmp_path / 'data', batch([('q1', 1)]), HOLD, receipts)
    target = tmp_path / 'schedule.json'
    target.write_text('{"previous": true}')
    assert main(['--data', str(data), '--output', str(target)]) != 0
    assert json.loads(target.read_text()) == {'previous': True}

"""Assign each call a route and start within worker and allowance limits."""


class ScheduleError(Exception):
    """The batch cannot be scheduled under the supplied rules."""


def schedule(batch, options, available):
    """Return {request_id: option} so every call fits workers and cumulative pool allowance.

    Allowance reserved at a start stays spent for every later start, so a call on
    pool p starting at t consumes p's remaining allowance at t and every later slot.
    Backtracking search with forward checking; options are tried earliest start
    first, then by route ID, so the result is deterministic.
    """
    slots = sorted(batch['slots'])
    remaining = {pool: {t: available[pool][str(t)] for t in slots} for pool in available}
    workers = {t: batch['workers'].get(str(t), 0) for t in slots}
    units = {q['id']: q['units'] for q in batch['requests']}
    missing = sorted(set(units) - set(options))
    if missing:
        raise ScheduleError('no route/start for %s' % missing[0])
    ordered = {r: sorted(opts, key=lambda o: (o['start'], o['route'])) for r, opts in options.items()}

    def fits(request_id, option):
        need, start = units[request_id], option['start']
        if workers[start] < need:
            return False
        return all(remaining[p][t] >= need for p in option['pools'] for t in slots if t >= start)

    def apply(request_id, option, sign):
        need, start = units[request_id] * sign, option['start']
        workers[start] -= need
        for pool in option['pools']:
            for t in slots:
                if t >= start:
                    remaining[pool][t] -= need

    chosen = {}

    def search(pending):
        if not pending:
            return True
        candidates = {r: [o for o in ordered[r] if fits(r, o)] for r in pending}
        # Most constrained request first; an empty candidate list means a dead end.
        request_id = min(pending, key=lambda r: (len(candidates[r]), r))
        rest = [r for r in pending if r != request_id]
        for option in candidates[request_id]:
            apply(request_id, option, 1)
            chosen[request_id] = option
            if search(rest):
                return True
            del chosen[request_id]
            apply(request_id, option, -1)
        return False

    if not search(sorted(units)):
        raise ScheduleError('no assignment of routes and starts fits the batch allowances')
    return chosen

import copy
import json
from pathlib import Path

import pytest

from reconcile.records import load
from reconcile.reservations import availability, replay

from test_runner import HOLD, batch

DATA = Path(__file__).resolve().parent.parent / 'data'


def reserve(rid, at, name='h1', attempt='a1', expires=4):
    return {'id': rid, 'kind': 'reserve', 'at': at, 'reservation': name, 'attempt': attempt, 'expires': expires}


def terminal(rid, kind, at, name='h1'):
    return {'id': rid, 'kind': kind, 'at': at, 'reservation': name}


def run(receipts, attempts=HOLD, as_of=1):
    doc = batch([])
    doc['as_of'] = as_of
    return replay(doc, {'attempts': list(attempts), 'receipts': list(receipts)})


def test_supplied_ledger_states_and_bindings():
    state = replay(*load(DATA))
    assert {name: entry['state'] for name, entry in state.items()} == {
        'expired': 'expired', 'held-A-early': 'held', 'held-A-late': 'held', 'held-B-late': 'held',
        'held-C-late': 'held', 'held-D-early': 'held', 'held-D-late': 'held', 'spent-C': 'committed'}
    # The commit stays charged to the original accepted attempt, not the rejected replacement chain.
    assert state['spent-C'] == {'key': 'settled-key', 'attempt': 'accepted-C', 'units': 1,
                                'pools': ['C', 'root'], 'expires': 6, 'state': 'committed'}
    # The replayed acknowledgment and timed-out retry do not charge the C hold twice.
    assert state['held-C-late']['units'] == 3 and state['held-C-late']['attempt'] == 'hold-C-late'
    assert 'unacknowledged' not in {entry['attempt'] for entry in state.values()}


def test_supplied_ledger_availability():
    batch_doc, ledger = load(DATA)
    assert availability(batch_doc, replay(batch_doc, ledger)) == {
        'A': {'10': 3, '11': 6, '12': 9}, 'B': {'10': 3, '11': 3, '12': 5},
        'C': {'10': 3, '11': 3, '12': 6}, 'D': {'10': 3, '11': 5, '12': 6},
        'root': {'10': 85, '11': 90, '12': 99}}


def test_receipt_rows_are_applied_in_effective_time_order():
    receipts = [terminal('c1', 'commit', 2), reserve('r1', 1), terminal('c1', 'commit', 2)]
    assert run(receipts, as_of=3)['h1']['state'] == 'committed'


def test_receipts_after_cutoff_have_no_effect():
    state = run([reserve('r1', 1), terminal('c1', 'commit', 2)], as_of=1)
    assert state['h1']['state'] == 'held'
    assert run([reserve('r1', 2)], as_of=1) == {}


def test_hold_expires_at_cutoff_without_terminal():
    assert run([reserve('r1', 1, expires=3)], as_of=3)['h1']['state'] == 'expired'


def test_late_repeat_commit_and_release_after_expiry_are_harmless():
    assert run([reserve('r1', 1, expires=3), terminal('c1', 'commit', 2), terminal('c2', 'commit', 5)],
               as_of=6)['h1']['state'] == 'committed'
    assert run([reserve('r1', 1, expires=3), terminal('x1', 'release', 5), terminal('x2', 'release', 6)],
               as_of=6)['h1']['state'] == 'released'


def test_reject_of_retry_keeps_original_reservation():
    attempts = HOLD + [{'id': 'a2', 'key': 'k1', 'at': 1, 'credentials': ['root'], 'units': 9, 'transport': 'error'}]
    receipts = [reserve('r1', 1), terminal('c1', 'commit', 2),
                {'id': 'j1', 'kind': 'reject', 'at': 2, 'attempt': 'a2'}]
    entry = run(receipts, attempts, as_of=3)['h1']
    assert (entry['attempt'], entry['units'], entry['pools'], entry['state']) == ('a1', 2, ['leaf', 'root'], 'committed')


@pytest.mark.parametrize('receipts, attempts', [
    ([reserve('r1', 1), terminal('c1', 'commit', 4)], HOLD),                          # first commit at expiry
    ([terminal('c1', 'commit', 1), reserve('r1', 2)], HOLD),                          # terminal before reserve
    ([reserve('r1', 1), terminal('c1', 'commit', 2), terminal('x1', 'release', 3)], HOLD),  # contradictory
    ([reserve('r1', 1), reserve('r2', 2, expires=5)], HOLD),                          # changed expiry
    ([reserve('r1', 1), reserve('r2', 2, attempt='a2')],
     HOLD + [{'id': 'a2', 'key': 'k1', 'at': 1, 'credentials': ['root'], 'units': 1, 'transport': 'response'}]),
    ([reserve('r1', 1), reserve('r2', 2, name='h2', attempt='a2')],                   # key bound twice
     HOLD + [{'id': 'a2', 'key': 'k1', 'at': 1, 'credentials': ['root'], 'units': 1, 'transport': 'response'}]),
    ([reserve('r1', 0, expires=0)], HOLD),                                            # acknowledged at expiry
    ([reserve('r1', 1), dict(reserve('r1', 1), expires=5)], HOLD),                    # conflicting receipt replay
    ([reserve('r1', 1, attempt='nope')], HOLD),                                       # unknown attempt
    ([terminal('c1', 'commit', 1, name='nope')], HOLD),                               # unknown reservation
    ([], HOLD + [dict(HOLD[0], units=3)]),                                            # conflicting attempt replay
    ([], [dict(HOLD[0], credentials=['root', 'ghost'])]),                             # unknown credential
    ([reserve('r1', 1, attempt='a2')],                                                # reserve precedes attempt
     HOLD + [{'id': 'a2', 'key': 'k2', 'at': 2, 'credentials': ['root'], 'units': 1, 'transport': 'response'}]),
])
def test_ledger_data_errors(receipts, attempts):
    with pytest.raises(ValueError):
        run(receipts, attempts, as_of=5)


def test_supplied_ledger_is_not_modified_by_replay():
    batch_doc, ledger = load(DATA)
    before = copy.deepcopy(ledger)
    replay(batch_doc, ledger)
    assert ledger == before == json.loads((DATA / 'ledger.json').read_text())
